// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // Only the current owner can successfully call setOwner
        address currentOwner = c.owner();
        vm.assume(_newOwner != currentOwner);

        // Act as the current owner
        vm.prank(currentOwner);

        // Call setOwner
        bool success = c.setOwner(_newOwner);

        // The owner should now be _newOwner
        assertTrue(success && c.owner() == _newOwner);
    }
}

